def _backfill_receipts(apps, schema_editor):
    """Give already-received purchase orders a receipt history, rebuilt from
    the stock movements those receipts wrote (same actor, same time). One
    receipt per (user, day) so a PO received over two shipments shows two.
    Orders that were never received, or predate movement logging, get none."""
