    DeliveryReceipt = apps.get_model('procurement', 'DeliveryReceipt')
    StockMovement = apps.get_model('inventory', 'StockMovement')

    for proc in Procurement.objects.filter(
        status__in=['Received', 'Partially Received'], receipts__isnull=True,
    ):
        seen = set()
        movements = StockMovement.objects.filter(
            movement_type='Procurement Received', reference_id=proc.pk,
        ).order_by('created_at', 'id')
        for movement in movements:
            key = (movement.created_by_id, movement.created_at.date())
            if key in seen:
                continue
            seen.add(key)
            DeliveryReceipt.objects.create(
                procurement=proc,
                received_by_id=movement.created_by_id,
                received_at=movement.created_at,
                receipt_date=movement.created_at.date(),
            )


